INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 7, 'theory', 'Quiz: subqueries');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 7, 0, 'How do you find products priced above the average price of all products?', '["WHERE price > AVG(price)", "WHERE price > (SELECT AVG(price) FROM products)", "HAVING price > AVG(price)", "WHERE price IN AVG(price)"]', 1, 'An aggregate can''t be used directly in WHERE; compute the average with a scalar subquery and compare against it.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 7, 1, 'Why can NOT IN (SELECT manager_id FROM employees) return an empty result?', '["NOT IN doesn''t work with subqueries", "If manager_id contains a NULL, the condition is never true", "NOT IN compares only with the first element", "The subquery is executed several times"]', 1, 'x <> NULL is UNKNOWN, so with a NULL in the list a NOT IN expression is never true. Use NOT EXISTS or filter out the NULLs.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 7, 2, 'What does "correlated subquery" mean?', '["A subquery that returns many rows", "A subquery that depends on columns of the outer query", "A subquery in the FROM part", "A subquery without WHERE"]', 1, 'A correlated subquery refers to columns of the outer row and, conceptually, is executed for each outer row.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 7, 3, 'What does a subquery in the FROM part need?', '["A mandatory LIMIT", "An alias", "The word TEMPORARY", "An index"]', 1, 'A derived table must have an alias (FROM (SELECT …) AS t), otherwise many databases raise an error.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 7, 4, 'What replaces x > ALL (SELECT price …) in SQLite?', '["x > (SELECT MAX(price) …)", "x > (SELECT MIN(price) …)", "x IN (SELECT price …)", "x > (SELECT AVG(price) …)"]', 0, 'Greater than all values means greater than the maximum. Remember: for an empty set MAX gives NULL, while ALL by the standard gives true.');
